            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO playout_region_grant"
                            + " (region_id, asset_id, valid_from_ms, valid_to_ms, created_at_ms)"
                            + " VALUES (?, ?, ?, ?, ?)", Statement.RETURN_GENERATED_KEYS);
