package com.example.starter.playout.api;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.PositiveOrZero;
import jakarta.validation.constraints.Size;

import java.time.OffsetDateTime;
import java.util.List;

/**
 * 播出编排 API 的请求与响应类型。时间字段统一为 Asia/Shanghai、毫秒精度 ISO 8601。
 */
public final class Dtos {

    private Dtos() {
    }

    /** 创建素材请求；id 为空时由系统生成稳定 ID。 */
    public record CreateAssetRequest(
            String id,
            @NotNull @Positive Long durationMs) {
    }

    /** 素材响应。 */
    public record AssetResponse(String id, long durationMs) {
    }

    /** 创建频道请求；fallbackAssetId 为不会被撤销的保底素材。 */
    public record CreateChannelRequest(
            String id,
            @NotBlank String fallbackAssetId) {
    }

    /** 频道响应。 */
    public record ChannelResponse(String id, String fallbackAssetId) {
    }

    /** 创建授权请求，有效区间 [validFrom, validTo) 左闭右开。 */
    public record CreateGrantRequest(
            @NotBlank String channelId,
            @NotBlank String assetId,
            @NotNull OffsetDateTime validFrom,
            @NotNull OffsetDateTime validTo) {
    }

    /** 授权响应。 */
    public record GrantResponse(
            long id,
            String channelId,
            String assetId,
            OffsetDateTime validFrom,
            OffsetDateTime validTo,
            boolean revoked) {
    }

    /** 撤销授权请求。 */
    public record RevokeGrantRequest(@NotBlank String requestId) {
    }

    /** 草稿片段输入；id 为空时由系统生成。 */
    public record SegmentInput(
            String id,
            @NotBlank String assetId,
            @NotNull OffsetDateTime start,
            @NotNull OffsetDateTime end) {
    }

    /** 整份替换草稿请求。 */
    public record ReplaceDraftRequest(
            @NotBlank String requestId,
            @NotNull @PositiveOrZero Long expectedDraftVersion,
            @NotNull List<@NotNull SegmentInput> segments) {
    }

    /** 草稿片段响应。 */
    public record SegmentResponse(
            String id,
            String assetId,
            OffsetDateTime start,
            OffsetDateTime end) {
    }

    /** 草稿响应。 */
    public record DraftResponse(
            String channelId,
            String businessDay,
            long version,
            List<SegmentResponse> segments) {
    }

    /** 发布请求。 */
    public record PublishRequest(
            @NotBlank String requestId,
            @NotNull @Positive Long draftVersion,
            @NotNull @PositiveOrZero Long expectedPublishedVersion) {
    }

    /** 发布响应。 */
    public record PublishResponse(
            long publicationId,
            String channelId,
            String businessDay,
            long publishedVersion,
            long draftVersion) {
    }

    /** 播出决定来源：EMERGENCY 命中紧急插播，PROGRAM 命中节目片段，FALLBACK 返回保底素材。 */
    public enum DecisionSource {
        EMERGENCY, PROGRAM, FALLBACK
    }

    /** 保底原因：无已发布编排 / 处于空档 / 覆盖片段的授权已撤销。 */
    public enum FallbackReason {
        NO_PUBLISHED_SCHEDULE, GAP, GRANT_REVOKED
    }

    /** 播出决定响应；source 为 FALLBACK 时 reason 非空；source 为 EMERGENCY 时 overrideKey 非空。 */
    public record PlayoutDecisionResponse(
            String channelId,
            OffsetDateTime at,
            String assetId,
            DecisionSource source,
            FallbackReason reason,
            Long publicationId,
            String segmentId,
            String overrideKey) {
    }

    /** 紧急插播状态：创建即 ACTIVE，取消后为 CANCELLED，均为终态语义（ACTIVE 只能转为 CANCELLED）。 */
    public enum OverrideStatus {
        ACTIVE, CANCELLED
    }

    /**
     * 创建限时紧急插播请求。区间 [start, end) 左闭右开、同处一个 Asia/Shanghai 业务日、
     * 时长大于 0 且不超过 30 分钟；priority 取值 1～9；grantId 必须属于该频道与素材并完整覆盖区间。
     */
    public record CreateEmergencyOverrideRequest(
            @NotBlank String requestId,
            @NotBlank String overrideKey,
            @NotBlank String channelId,
            @NotBlank String assetId,
            @NotNull @Positive Long grantId,
            @NotNull @Min(1) @Max(9) Integer priority,
            @NotNull OffsetDateTime start,
            @NotNull OffsetDateTime end) {
    }

    /** 取消紧急插播请求（幂等）。 */
    public record CancelEmergencyOverrideRequest(@NotBlank String requestId) {
    }

    /** 紧急插播明细响应，保存取消情况与原授权关联，不随授权撤销自动换绑。 */
    public record EmergencyOverrideResponse(
            String overrideKey,
            String channelId,
            String assetId,
            long grantId,
            int priority,
            OffsetDateTime start,
            OffsetDateTime end,
            OverrideStatus status,
            String cancelRequestId,
            OffsetDateTime cancelledAt,
            OffsetDateTime createdAt) {
    }

    // ---------- 区域切换 ----------

    /** 创建区域请求；id 为空时由系统生成稳定 ID。 */
    public record CreateRegionRequest(String id) {
    }

    /** 区域响应。 */
    public record RegionResponse(String id, OffsetDateTime createdAt) {
    }

    /**
     * 创建区域授权请求，授权窗口 [validFrom, validTo) 左闭右开，时间为 UTC（偏移 +00:00 表达）。
     * 授权撤销为终态，只影响之后的编排，不追改历史占位。
     */
    public record CreateRegionGrantRequest(
            @NotBlank String regionId,
            @NotBlank String assetId,
            @NotNull OffsetDateTime validFrom,
            @NotNull OffsetDateTime validTo) {
    }

    /** 区域授权响应；revoked 为当前状态。 */
    public record RegionGrantResponse(
            long id,
            String regionId,
            String assetId,
            OffsetDateTime validFrom,
            OffsetDateTime validTo,
            boolean revoked) {
    }

    /** 撤销区域授权请求（幂等）。 */
    public record RevokeRegionGrantRequest(@NotBlank String requestId) {
    }

    /**
     * 区域时段输入：编排员把素材分配给某区域的 UTC 播出时段 [start, end)。
     * 时段按 UTC 纪元毫秒判重，与表达偏移无关。
     */
    public record RegionSegmentInput(
            @NotBlank String regionId,
            @NotBlank String assetId,
            @NotNull OffsetDateTime start,
            @NotNull OffsetDateTime end) {
    }

    /**
     * 区域编排提交请求。同一 requestId 重放首次区域清单；换素材或时段返回 409。
     * 一次提交可包含多个区域，每个区域可有多个不重叠（相邻可接续）时段。
     */
    public record SubmitRegionScheduleRequest(
            @NotBlank String requestId,
            @NotNull @Size(min = 1) List<@NotNull RegionSegmentInput> segments) {
    }

    /** 单条占位的提交结果明细，固化素材与授权版本。 */
    public record RegionAllocationResponse(
            long id,
            String requestId,
            String regionId,
            String assetId,
            long grantId,
            OffsetDateTime grantValidFrom,
            OffsetDateTime grantValidTo,
            OffsetDateTime start,
            OffsetDateTime end,
            OffsetDateTime createdAt) {
    }

    /** 整次编排提交结果；按请求提交顺序返回各区域占位。 */
    public record RegionScheduleResponse(
            String requestId,
            List<RegionAllocationResponse> allocations) {
    }

    /** 区域占位查询项（编排员视角，含固化的授权版本）。 */
    public record RegionOccupancyResponse(
            long id,
            String requestId,
            String regionId,
            String assetId,
            long grantId,
            OffsetDateTime grantValidFrom,
            OffsetDateTime grantValidTo,
            OffsetDateTime start,
            OffsetDateTime end) {
    }

    /** 整单 422 时单个区域时段的冲突原因。 */
    public record RegionConflictResponse(
            String regionId,
            String assetId,
            OffsetDateTime start,
            OffsetDateTime end,
            String reason,
            String detail) {
    }

    /** 统一错误响应体。 */
    public record ErrorResponse(String error, String message) {
    }
}

package com.example.starter.playout.api;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.PositiveOrZero;
import jakarta.validation.constraints.Size;

import java.time.OffsetDateTime;
import java.util.List;

/**
 * 播出编排 API 的请求与响应类型。时间字段统一为 Asia/Shanghai、毫秒精度 ISO 8601。
 */
public final class Dtos {

    private Dtos() {
    }

    /** 创建素材请求；id 为空时由系统生成稳定 ID。 */
    public record CreateAssetRequest(
            String id,
            @NotNull @Positive Long durationMs) {
    }

    /** 素材响应。 */
    public record AssetResponse(String id, long durationMs) {
    }

    /** 创建频道请求；fallbackAssetId 为不会被撤销的保底素材。 */
    public record CreateChannelRequest(
            String id,
            @NotBlank String fallbackAssetId) {
    }

    /** 频道响应。 */
    public record ChannelResponse(String id, String fallbackAssetId) {
    }

    /** 创建授权请求，有效区间 [validFrom, validTo) 左闭右开。 */
    public record CreateGrantRequest(
            @NotBlank String channelId,
            @NotBlank String assetId,
            @NotNull OffsetDateTime validFrom,
            @NotNull OffsetDateTime validTo) {
    }

    /** 授权响应。 */
    public record GrantResponse(
            long id,
            String channelId,
            String assetId,
            OffsetDateTime validFrom,
            OffsetDateTime validTo,
            boolean revoked) {
    }

    /** 撤销授权请求。 */
    public record RevokeGrantRequest(@NotBlank String requestId) {
    }

    /** 草稿片段输入；id 为空时由系统生成。 */
    public record SegmentInput(
            String id,
            @NotBlank String assetId,
            @NotNull OffsetDateTime start,
            @NotNull OffsetDateTime end) {
    }

    /** 整份替换草稿请求。 */
    public record ReplaceDraftRequest(
            @NotBlank String requestId,
            @NotNull @PositiveOrZero Long expectedDraftVersion,
            @NotNull List<@NotNull SegmentInput> segments) {
    }

    /** 草稿片段响应。 */
    public record SegmentResponse(
            String id,
            String assetId,
            OffsetDateTime start,
            OffsetDateTime end) {
    }

    /** 草稿响应。 */
    public record DraftResponse(
            String channelId,
            String businessDay,
            long version,
            List<SegmentResponse> segments) {
    }

    /** 发布请求。 */
    public record PublishRequest(
            @NotBlank String requestId,
            @NotNull @Positive Long draftVersion,
            @NotNull @PositiveOrZero Long expectedPublishedVersion) {
    }

    /** 发布响应。 */
    public record PublishResponse(
            long publicationId,
            String channelId,
            String businessDay,
            long publishedVersion,
            long draftVersion) {
    }

    /** 播出决定来源：EMERGENCY 命中紧急插播，PROGRAM 命中节目片段，FALLBACK 返回保底素材。 */
    public enum DecisionSource {
        EMERGENCY, PROGRAM, FALLBACK
    }

    /** 保底原因：无已发布编排 / 处于空档 / 覆盖片段的授权已撤销。 */
    public enum FallbackReason {
        NO_PUBLISHED_SCHEDULE, GAP, GRANT_REVOKED
    }

    /** 播出决定响应；source 为 FALLBACK 时 reason 非空；source 为 EMERGENCY 时 overrideKey 非空。 */
    public record PlayoutDecisionResponse(
            String channelId,
            OffsetDateTime at,
            String assetId,
            DecisionSource source,
            FallbackReason reason,
            Long publicationId,
            String segmentId,
            String overrideKey) {
    }

    /** 紧急插播状态：创建即 ACTIVE，取消后为 CANCELLED，均为终态语义（ACTIVE 只能转为 CANCELLED）。 */
    public enum OverrideStatus {
        ACTIVE, CANCELLED
    }

    /**
     * 创建限时紧急插播请求。区间 [start, end) 左闭右开、同处一个 Asia/Shanghai 业务日、
     * 时长大于 0 且不超过 30 分钟；priority 取值 1～9；grantId 必须属于该频道与素材并完整覆盖区间。
     */
    public record CreateEmergencyOverrideRequest(
            @NotBlank String requestId,
            @NotBlank String overrideKey,
            @NotBlank String channelId,
            @NotBlank String assetId,
            @NotNull @Positive Long grantId,
            @NotNull @Min(1) @Max(9) Integer priority,
            @NotNull OffsetDateTime start,
            @NotNull OffsetDateTime end) {
    }

    /** 取消紧急插播请求（幂等）。 */
    public record CancelEmergencyOverrideRequest(@NotBlank String requestId) {
    }

    /** 紧急插播明细响应，保存取消情况与原授权关联，不随授权撤销自动换绑。 */
    public record EmergencyOverrideResponse(
            String overrideKey,
            String channelId,
            String assetId,
            long grantId,
            int priority,
            OffsetDateTime start,
            OffsetDateTime end,
            OverrideStatus status,
            String cancelRequestId,
            OffsetDateTime cancelledAt,
            OffsetDateTime createdAt) {
    }

    // ---------- 区域切换 ----------

    /** 创建区域请求；id 为空时由系统生成稳定 ID。 */
    public record CreateRegionRequest(String id) {
    }

    /** 区域响应。 */
    public record RegionResponse(String id, OffsetDateTime createdAt) {
    }

    /**
     * 创建区域授权请求，授权窗口 [validFrom, validTo) 左闭右开，时间为 UTC（偏移 +00:00 表达）。
     * 授权撤销为终态，只影响之后的编排，不追改历史占位。
     */
    public record CreateRegionGrantRequest(
            @NotBlank String regionId,
            @NotBlank String assetId,
            @NotNull OffsetDateTime validFrom,
            @NotNull OffsetDateTime validTo) {
    }

    /** 区域授权响应；revoked 为当前状态。 */
    public record RegionGrantResponse(
            long id,
            String regionId,
            String assetId,
            OffsetDateTime validFrom,
            OffsetDateTime validTo,
            boolean revoked) {
    }

    /** 撤销区域授权请求（幂等）。 */
    public record RevokeRegionGrantRequest(@NotBlank String requestId) {
    }

    /**
     * 区域时段输入：编排员把素材分配给某区域的 UTC 播出时段 [start, end)。
     * 时段按 UTC 纪元毫秒判重，与表达偏移无关。
     */
    public record RegionSegmentInput(
            @NotBlank String regionId,
            @NotBlank String assetId,
            @NotNull OffsetDateTime start,
            @NotNull OffsetDateTime end) {
    }

    /**
     * 区域编排提交请求。同一 requestId 重放首次区域清单；换素材或时段返回 409。
     * 一次提交可包含多个区域，每个区域可有多个不重叠（相邻可接续）时段。
     */
    public record SubmitRegionScheduleRequest(
            @NotBlank String requestId,
            @NotNull @Size(min = 1) List<@NotNull @Valid RegionSegmentInput> segments) {
    }

    /** 单条占位的提交结果明细，固化素材与授权版本。 */
    public record RegionAllocationResponse(
            long id,
            String requestId,
            String regionId,
            String assetId,
            long grantId,
            OffsetDateTime grantValidFrom,
            OffsetDateTime grantValidTo,
            OffsetDateTime start,
            OffsetDateTime end,
            OffsetDateTime createdAt) {
    }

    /** 整次编排提交结果；按请求提交顺序返回各区域占位。 */
    public record RegionScheduleResponse(
            String requestId,
            List<RegionAllocationResponse> allocations) {
    }

    /** 区域占位查询项（编排员视角，含固化的授权版本）。 */
    public record RegionOccupancyResponse(
            long id,
            String requestId,
            String regionId,
            String assetId,
            long grantId,
            OffsetDateTime grantValidFrom,
            OffsetDateTime grantValidTo,
            OffsetDateTime start,
            OffsetDateTime end) {
    }

    /** 整单 422 时单个区域时段的冲突原因。 */
    public record RegionConflictResponse(
            String regionId,
            String assetId,
            OffsetDateTime start,
            OffsetDateTime end,
            String reason,
            String detail) {
    }

    /** 统一错误响应体。 */
    public record ErrorResponse(String error, String message) {
    }
}

